{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "The highest-transfer analogue, containing an amidinophenyl group and multiple carboxylates, had absolute bioavailability not high enough for oral use in humans, directly supporting low F for the query's amidine/zwitterionic scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "DX-9065a, a structurally close non-peptidic small molecule with strong basic amidino groups and a carboxylic acid, had human absolute oral bioavailability of only 2–3%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "In fasted humans, DX-9065 given as a conventional capsule had oral bioavailability of 3%, matching the query's fasted condition and supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C22"],
      "claim": "Pentamidine, a bis-amidine dicationic drug, is noted for poor oral bioavailability, reinforcing the permeability liability of the amidine motif present in the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "The zwitterionic perindoprilat (S-9780) after oral prodrug in young healthy subjects had F = 19 ± 7%, below the 20% threshold, supporting low F for a similar peptide-like zwitterion.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Revefenacin, a large polar/ionizable oral drug, had absolute bioavailability <3%, supporting low F for highly polar structures.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Tolperisone has very low oral bioavailability in humans, providing weaker supportive evidence that ionizable polar drugs can fail the F ≥ 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Perindoprilat availability was 30 ± 6% in cirrhotic patients after oral perindopril, but this reflects a prodrug and altered liver function, so it is only weak contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C07"],
      "claim": "GPG-NH2 showed 100% bioavailability only at a nanogram microdose, a condition not representative of therapeutic oral absorption; weak contradictory evidence.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C01"],
      "claim": "Encainide showed 76 ± 17% oral bioavailability in cirrhosis, but lacks the amidine/carboxylate polarity of the query and is confounded by hepatic disease; weak contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar zwitterionic amidine/carboxylate peptidomimetic. Multiple high-transfer human analogues with the same amidine/zwitterionic pharmacophore show very low oral bioavailability (DX-9065a 2–3%, pentamidine poor, amidine-carboxylate analogue not orally viable), and the fasted-state DX-9065 record is directly applicable. The few higher F values come from cirrhotic patients, prodrug, or microdose conditions and do not outweigh the consistent low-F evidence. Therefore F < 20% is strongly supported.",
  "evidence_gaps": [
    "No direct human oral bioavailability measurement exists for the exact query molecule.",
    "No data address possible active uptake, efflux, or prodrug behavior for the query.",
    "Disease-state and prodrug records complicate extrapolation from perindoprilat and encainide."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

